/*
 logo.js - Specialise Products logo file
*/

import { h } from "preact"
import { useSettingsContext } from "../../../contexts"

const AppLogo = ({
    height = "120px",
    color = "currentColor",
    bgcolor = "white",
}) => {
    const { interfaceSettings } = useSettingsContext()
    if (
        interfaceSettings.current &&
        interfaceSettings.current.custom &&
        interfaceSettings.current.custom.logo
    )
        return (
            <span
                dangerouslySetInnerHTML={{
                    __html: interfaceSettings.current.custom.logo
                        .replace("{height}", height)
                        .replaceAll("{color}", color)
                        .replaceAll("{bgcolor}", bgcolor),
                }}
            ></span>
        )
    else
        return (
            <svg
                height={height}
                viewBox="0 0 200 200"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
                class="esp3dlogo"
            >
                {/* Background */}
                <circle cx="100" cy="100" r="99" fill="white" />

                {/* Outer Ring - Radius 98 */}
                <circle cx="100" cy="100" r="98" stroke="#F36F21" stroke-width="2.5" />

                {/* Inner Ring - Radius 68 */}
                <circle cx="100" cy="100" r="68" stroke="#5E35B1" stroke-width="2.5" />

                {/* Side Brand Dots */}
                <circle cx="16" cy="100" r="4.5" fill="#F36F21" />
                <circle cx="184" cy="100" r="4.5" fill="#F36F21" />

                <defs>
                    {/* 
                        Centering Logic:
                        Circles at R=98 and R=68. Gap center is R=83.
                        
                        Top Path: Left to Right, Clockwise (Sweep=1). 
                        Walking L->R, Left is Outside. Up = Outside.
                    */}
                    <path id="topTextArc" d="M 17,100 A 83,83 0 0,1 183,100" />

                    {/* 
                        Bottom Path: Left to Right, Counter-Clockwise (Sweep=0).
                        Walking L->R, Left is Inside. Up = Center.
                    */}
                    <path id="bottomTextArc" d="M 17,100 A 83,83 0 0,0 183,100" />
                </defs>

                {/* Top Arched Text: SPECIALISED PRODUCTS */}
                <text font-family="'Outfit', 'Impact', sans-serif" font-size="20" font-weight="900" fill="#F36F21" dominant-baseline="central">
                    <textPath href="#topTextArc" startOffset="50%" text-anchor="middle">
                        SPECIALISED PRODUCTS
                    </textPath>
                </text>

                {/* Bottom Arched Text: Customized Solutions Company */}
                <text font-family="'Inter', sans-serif" font-size="11" font-weight="700" fill="#5E35B1" dominant-baseline="central">
                    <textPath href="#bottomTextArc" startOffset="50%" text-anchor="middle">
                        Customized Solutions Company
                    </textPath>
                </text>

                {/* Gear & Wrench - Center Icons */}
                <g transform="translate(100, 100) scale(0.82)">
                    {/* 8-Tooth Orange Gear */}
                    <path
                        d="M 12.8,-48.3 L 12.8,-35.1 A 38.3,38.3 0 0,1 25.1,-30 L 34.4,-39.3 L 44.7,-29 L 35.4,-19.7 A 38.3,38.3 0 0,1 38.3,-6.4 L 51.5,-6.4 L 51.5,6.4 L 38.3,6.4 A 38.3,38.3 0 0,1 35.4,19.7 L 44.7,29 L 34.4,39.3 L 25.1,30 A 38.3,38.3 0 0,1 12.8,35.1 L 12.8,48.3 L -12.8,48.3 L -12.8,35.1 A 38.3,38.3 0 0,1 -25.1,30 L -34.4,39.3 L -44.7,29 L -35.4,19.7 A 38.3,38.3 0 0,1 -38.3,6.4 L -51.5,6.4 L -51.5,-6.4 L -38.3,-6.4 A 38.3,38.3 0 0,1 -35.4,-19.7 L -44.7,-29 L -34.4,-39.3 L -25.1,-30 A 38.3,38.3 0 0,1 -12.8,-35.1 L -12.8,-48.3 Z M 0,-25.5 A 25.5,25.5 0 0,0 0,25.5 A 25.5,25.5 0 0,0 0,-25.5 Z"
                        fill="#F36F21"
                    />

                    {/* Purple/White Wrench */}
                    <g transform="rotate(-45)">
                        <rect x="-8" y="-45" width="16" height="55" rx="4" fill="white" stroke="#5E35B1" stroke-width="5" />
                        <path
                            d="M -22,-60 C -25,-50 -20,-35 0,-35 C 20,-35 25,-50 22,-60 L 15,-55 C 18,-48 15,-42 0,-42 C -15,-42 -18,-48 -15,-55 Z"
                            fill="white"
                            stroke="#5E35B1"
                            stroke-width="5"
                            stroke-linejoin="round"
                        />
                        <circle cx="0" cy="18" r="18" fill="white" stroke="#5E35B1" stroke-width="5" />
                        <path
                            d="M 0,8.5 L 8.6,13.2 L 8.2,22.8 L 0,27.5 L -8.2,22.8 L -8.6,13.2 Z"
                            fill="white"
                            stroke="#5E35B1"
                            stroke-width="3"
                        />
                    </g>
                </g>
            </svg>
        )
}

export { AppLogo }
