===============\n// 🎭 BESPOKE DASHBOARD HEADER: SPECIALISE PRODUCTS\n// ============================================\n\n.navbar {\n    height: 90px;\n    padding: 0 40px;\n    background: linear-gradient(180deg, rgba(5, 8, 17, 0.95) 0%, rgba(5, 8, 17, 0.8) 100%);\n    backdrop-filter: blur(30px);\n    -webkit-backdrop-filter: blur(30px);\n    border-bottom: 1px solid rgba(243, 111, 33, 0.15);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    box-shadow: 0 10px 50px rgba(0, 0, 0, 0.5);\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    z-index: 1000;\n\n    &::before {\n        content: '';\n        position: absolute;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 1px;\n        background: linear-gradient(90deg, transparent 0%, rgba(243, 111, 33, 0.5) 50%, transparent 100%);\n    }\n}\n\n// Bespoke Navigation Pills\n.navbar-section {\n    display: flex;\n    align-items: center;\n    gap: 15px;\n}\n\n.tab-item {\n    padding: 0;\n    margin: 0;\n\n    a,\n    .btn {\n        display: flex;\n        align-items: center;\n        gap: 10px;\n        padding: 12px 24px;\n        border-radius: 14px;\n        font-family: $font-heading;\n        font-size: 15px;\n        font-weight: 600;\n        color: rgba(255, 255, 255, 0.6) !important;\n        text-decoration: none !important;\n        transition: all $transition-base;\n        border: 1px solid transparent;\n        background: transparent;\n\n        svg {\n            width: 18px;\n            height: 18px;\n            transition: transform $transition-base;\n        }\n\n        &:hover {\n            color: $brand-orange !important;\n            background: rgba(243, 111, 33, 0.08);\n            border-color: rgba(243, 111, 33, 0.2);\n            transform: translateY(-2px);\n\n            svg {\n                transform: scale(1.1);\n            }\n        }\n\n        &.active {\n            color: white !important;\n            background: linear-gradient(135deg, $brand-orange 0%, #FF8C42 100%);\n            border-color: transparent;\n            box-shadow: $shadow-glow;\n\n            svg {\n                color: white;\n            }\n        }\n    }\n}\n\n// Logo Container Customization\n.navbar-brand.logo {\n    display: flex;\n    align-items: center;\n    gap: 15px;\n    height: 100%;\n\n    &::after {\n        content: 'PRECISION CONSOLE';\n        font-family: $font-heading;\n        font-size: 11px;\n        font-weight: 800;\n        letter-spacing: 0.15em;\n        color: $brand-orange;\n        border-left: 1px solid rgba(255, 255, 255, 0.1);\n        padding-left: 15px;\n        opacity: 0.8;\n    }\n\n    .esp3dlogo {\n        height: 55px !important; // Controlled size for bespoke header\n        width: auto;\n        filter: drop-shadow(0 0 15px rgba(243, 111, 33, 0.2));\n        border-radius: 12px;\n        background: white;\n        padding: 4px;\n    }\n}\n\n// Connection Button - Enterprise Style\n.tab-item .btn-link {\n    background: rgba(94, 53, 177, 0.15) !important;\n    border: 1px solid rgba(94, 53, 177, 0.3) !important;\n    color: $secondary-color-light !important;\n    border-radius: 12px !important;\n    padding: 10px 20px !important;\n\n    &:hover {\n        background: $brand-purple !important;\n        color: white !important;\n        box-shadow: $shadow-glow-purple;\n    }\n}\n\n// Mobile Overrides\n@media (max-width: $size-md) {\n    .navbar {\n        height: 70px;\n        padding: 0 20px;\n\n        &::after {\n            display: none; // Hide \"PRECISION CONSOLE\" text on mobile\n        }\n    }\n}","// ============================================\n// 🎨 MODERN PANEL STYLES\n// ============================================\n\n.panel-dashboard,\n.panel-interface,\n.panel-features {\n    user-select: none;\n    -moz-user-select: none;\n    -webkit-user-select: none;\n    -ms-user-select: none;\n}\n\n.macro-buttons-panel {\n    display: -ms-flexbox;\n    display: flex;\n    flex-flow: row wrap;\n    justify-content: space-between;\n    align-content: stretch;\n    gap: $layout-spacing;\n}\n\n.panel {\n    display: -ms-flexbox;\n    display: flex;\n    flex-flow: column;\n    height: 550px;\n    overflow-y: auto !important;\n    overflow-x: hidden !important;\n    background: rgba(30, 41, 59, 0.6);\n    backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px);\n    border: 1px solid rgba(148, 163, 184, 0.2);\n    border-radius: $border-radius-lg;\n    box-shadow: $shadow-md;\n    transition: all $transition-base;\n    color: $body-font-color;\n\n    // Custom scrollbar for panels\n    &::-webkit-scrollbar {\n        width: 8px;\n    }\n\n    &::-webkit-scrollbar-track {\n        background: rgba(15, 23, 42, 0.3);\n        border-radius: $border-radius-full;\n    }\n\n    &::-webkit-scrollbar-thumb {\n        background: rgba(79, 70, 229, 0.4);\n        border-radius: $border-radius-full;\n\n        &:hover {\n            background: rgba(79, 70, 229, 0.6);\n        }\n    }\n\n    &:hover {\n        border-color: rgba(148, 163, 184, 0.3);\n        box-shadow: $shadow-lg;\n        transform: translateY(-2px);\n    }\n}\n\n.panel-body-dashboard,\n.panel-body-interface,\n.panel-body-features {\n    display: -ms-flexbox;\n    display: flex;\n    flex-flow: column;\n    padding: $layout-spacing;\n}\n\n.panel .navbar,\n.panel .navbar-section {\n    background: linear-gradient(135deg, rgba(79, 70, 229, 0.15) 0%, rgba(6, 182, 212, 0.15) 100%);\n    color: $secondary-color;\n    border-bottom: 1px solid rgba(148, 163, 184, 0.2);\n    padding: $layout-spacing-sm $layout-spacing;\n    font-family: $font-heading;\n    font-weight: 600;\n    letter-spacing: 0.025em;\n}\n\n.panel-item {\n    flex: 0 1 auto;\n    padding: $layout-spacing-sm;\n    transition: background $transition-base;\n    border-radius: $border-radius;\n\n    &:hover {\n        background: rgba(79, 70, 229, 0.05);\n    }\n}\n\n.files-list-footer {\n    padding: $layout-spacing $layout-spacing-lg !important;\n    background: rgba(15, 23, 42, 0.5);\n    border-top: 1px solid rgba(148, 163, 184, 0.2);\n}\n\n.column {\n    .panel {\n        height: 100%;\n        box-shadow: $shadow-lg;\n\n        &:hover {\n            box-shadow: $shadow-xl;\n        }\n    }\n}\n\n.loading-panel {\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 100%;\n    width: 100%;\n\n    .spinner {\n        width: 48px;\n        height: 48px;\n        border: 4px solid rgba(148, 163, 184, 0.2);\n        border-top-color: $primary-color;\n        border-radius: 50%;\n        animation: spin 0.8s linear infinite;\n    }\n}\n\n// Panel Header Enhancements\n.panel-header {\n    background: linear-gradient(135deg, rgba(79, 70, 229, 0.1) 0%, rgba(6, 182, 212, 0.1) 100%);\n    border-bottom: 1px solid rgba(148, 163, 184, 0.2);\n    padding: $layout-spacing $layout-spacing-lg;\n\n    .panel-title {\n        font-family: $font-heading;\n        font-weight: 700;\n        font-size: $font-size-lg;\n        color: $secondary-color;\n        text-transform: uppercase;\n        letter-spacing: 0.05em;\n    }\n}\n\n// Panel Footer\n.panel-footer {\n    background: rgba(15, 23, 42, 0.5);\n    border-top: 1px solid rgba(148, 163, 184, 0.2);\n    padding: $layout-spacing $layout-spacing-lg;\n    margin-top: auto;\n}","@media (max-width: 480px) {\n    .hide-low {\n        display: none !important;\n    }\n    .show-low {\n        display: block !important;\n    }\n    section .active,\n    li .active {\n        background-color: rgba(100, 100, 100, 0.1) !important;\n    }\n    .btn-header,\n    .btn-close {\n        color: white !important;\n        background-color: blue !important;\n    }\n}\n","// ============================================\r\n// 🎨 BESPOKE ENTERPRISE THEME: SPECIALISE PRODUCTS\r\n// ============================================\r\n\r\n// High-End Glassmorphism\r\n.glass-effect {\r\n  background: rgba(15, 23, 42, 0.4);\r\n  backdrop-filter: blur(30px);\r\n  -webkit-backdrop-filter: blur(30px);\r\n  border: 1px solid rgba(255, 255, 255, 0.05);\r\n  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.3);\r\n}\r\n\r\n.glass-card {\r\n  @extend .glass-effect;\r\n  border-radius: 24px;\r\n  padding: 30px;\r\n  transition: all $transition-base;\r\n  margin-bottom: 24px;\r\n\r\n  &:hover {\r\n    background: rgba(15, 23, 42, 0.55);\r\n    border-color: rgba(243, 111, 33, 0.2);\r\n    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.4);\r\n    transform: translateY(-5px);\r\n  }\r\n}\r\n\r\n// Brand Buttons\r\n.btn-modern {\r\n  position: relative;\r\n  overflow: hidden;\r\n  font-family: $font-heading;\r\n  font-weight: 700;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.1em;\r\n  border-radius: 14px;\r\n  padding: 12px 28px;\r\n  transition: all $transition-base;\r\n  border: none;\r\n  cursor: pointer;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 10px;\r\n\r\n  &::before {\r\n    content: '';\r\n    position: absolute;\r\n    top: 0;\r\n    left: -100%;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);\r\n    transition: left 0.6s ease-in-out;\r\n  }\r\n\r\n  &:hover::before {\r\n    left: 100%;\r\n  }\r\n\r\n  &:hover {\r\n    transform: translateY(-3px);\r\n  }\r\n}\r\n\r\n.btn-primary-modern {\r\n  @extend .btn-modern;\r\n  background: linear-gradient(135deg, $brand-orange 0%, #FF8C42 100%);\r\n  color: white;\r\n  box-shadow: 0 10px 25px rgba(243, 111, 33, 0.3);\r\n\r\n  &:hover {\r\n    box-shadow: 0 15px 35px rgba(243, 111, 33, 0.45);\r\n  }\r\n}\r\n\r\n.btn-secondary-modern {\r\n  @extend .btn-modern;\r\n  background: linear-gradient(135deg, $brand-purple 0%, #7E57C2 100%);\r\n  color: white;\r\n  box-shadow: 0 10px 25px rgba(94, 53, 177, 0.3);\r\n\r\n  &:hover {\r\n    box-shadow: 0 15px 35px rgba(94, 53, 177, 0.45);\r\n  }\r\n}\r\n\r\n// Bespoke Background Blobs\r\n.modern-bg-container {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n  z-index: -10;\r\n  overflow: hidden;\r\n  background: radial-gradient(circle at 50% 50%, #0A0F1D 0%, #020408 100%);\r\n\r\n  &::after {\r\n    content: '';\r\n    position: absolute;\r\n    width: 100%;\r\n    height: 100%;\r\n    background-image: radial-gradient(rgba(243, 111, 33, 0.05) 1px, transparent 1px);\r\n    background-size: 50px 50px;\r\n    opacity: 0.3;\r\n  }\r\n\r\n  .blob {\r\n    position: absolute;\r\n    filter: blur(120px);\r\n    opacity: 0.12;\r\n    border-radius: 50%;\r\n    animation: blobFloat 25s infinite alternate ease-in-out;\r\n  }\r\n\r\n  .blob-1 {\r\n    width: 600px;\r\n    height: 600px;\r\n    background: $brand-orange;\r\n    top: -200px;\r\n    left: -100px;\r\n  }\r\n\r\n  .blob-2 {\r\n    width: 500px;\r\n    height: 500px;\r\n    background: $brand-purple;\r\n    bottom: -150px;\r\n    right: -100px;\r\n    animation-delay: -5s;\r\n  }\r\n\r\n  .blob-3 {\r\n    width: 400px;\r\n    height: 400px;\r\n    background: #FFD93D;\r\n    bottom: 30%;\r\n    left: 20%;\r\n    opacity: 0.05;\r\n    animation-delay: -12s;\r\n  }\r\n}\r\n\r\n@keyframes blobFloat {\r\n  0% {\r\n    transform: translate(0, 0) scale(1);\r\n  }\r\n\r\n  33% {\r\n    transform: translate(100px, 150px) scale(1.2);\r\n  }\r\n\r\n  66% {\r\n    transform: translate(-50px, 100px) scale(0.8);\r\n  }\r\n\r\n  100% {\r\n    transform: translate(0, 0) scale(1);\r\n  }\r\n}\r\n\r\n// Global Text Overrides for Enterprise look\r\nh1,\r\nh2,\r\nh3,\r\nh4 {\r\n  font-family: $font-heading;\r\n  font-weight: 800;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n  color: white;\r\n  margin-bottom: 25px;\r\n}\r\n\r\n// Customized Loading\r\n.loading::after {\r\n  border-color: $brand-orange !important;\r\n  border-right-color: transparent !important;\r\n  border-top-color: transparent !important;\r\n  box-shadow: 0 0 15px $brand-orange;\r\n}","// ============================================\r\n// 🎨 MODERN CONTROL ENHANCEMENTS\r\n// ============================================\r\n\r\n// Modern Button Overrides\r\n.btn {\r\n  font-family: $font-heading;\r\n  font-weight: 600;\r\n  border-radius: $border-radius;\r\n  transition: all $transition-base;\r\n  border: 1px solid transparent;\r\n\r\n  &:hover {\r\n    transform: translateY(-1px);\r\n    box-shadow: $shadow;\r\n  }\r\n\r\n  &:active {\r\n    transform: translateY(0);\r\n  }\r\n}\r\n\r\n.btn-primary {\r\n  background: $primary-gradient;\r\n  color: white;\r\n  border: none;\r\n  box-shadow: $shadow-glow;\r\n\r\n  &:hover {\r\n    box-shadow: $shadow-glow, $shadow-md;\r\n  }\r\n}\r\n\r\n.btn-success {\r\n  background: linear-gradient(135deg, $success-color 0%, darken($success-color, 10%) 100%);\r\n  color: white;\r\n  border: none;\r\n\r\n  &:hover {\r\n    box-shadow: 0 0 15px rgba(16, 185, 129, 0.4);\r\n  }\r\n}\r\n\r\n.btn-error,\r\n.emergency-btn {\r\n  background: linear-gradient(135deg, $error-color 0%, darken($error-color, 10%) 100%);\r\n  color: white !important;\r\n  border: none !important;\r\n  box-shadow: 0 0 15px rgba(239, 68, 68, 0.4);\r\n\r\n  &:hover {\r\n    background: linear-gradient(135deg, lighten($error-color, 5%) 0%, $error-color 100%) !important;\r\n    box-shadow: 0 0 20px rgba(239, 68, 68, 0.6);\r\n  }\r\n\r\n  &:active {\r\n    background: $error-color !important;\r\n  }\r\n}\r\n\r\n.btn-header {\r\n  background: rgba(79, 70, 229, 0.1);\r\n  color: $secondary-color;\r\n  border: 1px solid rgba(79, 70, 229, 0.3);\r\n\r\n  &:hover {\r\n    background: rgba(79, 70, 229, 0.2);\r\n  }\r\n}\r\n\r\n.mobile-view .btn-header,\r\n.btn-header:hover,\r\n.mobile-view .btn-close,\r\n.btn-close:hover {\r\n  color: white !important;\r\n  background: $primary-color !important;\r\n}\r\n\r\n// Modern Input Styles\r\n.form-input,\r\n.form-select {\r\n  background: rgba(30, 41, 59, 0.5);\r\n  border: 1px solid rgba(148, 163, 184, 0.2);\r\n  border-radius: $border-radius;\r\n  color: $body-font-color !important;\r\n  transition: all $transition-base;\r\n\r\n  &:focus {\r\n    outline: none;\r\n    border-color: $primary-color;\r\n    background: rgba(30, 41, 59, 0.7);\r\n    box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);\r\n  }\r\n\r\n  &::placeholder {\r\n    color: $gray-color;\r\n  }\r\n}\r\n\r\n// Terminal Styling\r\n.terminal {\r\n  background: rgba(15, 23, 42, 0.8);\r\n  border: 1px solid rgba(148, 163, 184, 0.2);\r\n  border-radius: $border-radius-lg;\r\n  color: $body-font-color;\r\n  font-family: $mono-font-family;\r\n\r\n  .echo {\r\n    color: $secondary-color;\r\n  }\r\n\r\n  .error {\r\n    color: $error-color;\r\n    font-weight: bolder;\r\n  }\r\n}\r\n\r\n// File List Styling\r\n.files-list {\r\n  background: rgba(15, 23, 42, 0.3);\r\n  border: 1px solid rgba(148, 163, 184, 0.2);\r\n  border-radius: $border-radius-lg;\r\n\r\n  &::-webkit-scrollbar {\r\n    width: 8px;\r\n  }\r\n\r\n  &::-webkit-scrollbar-track {\r\n    background: rgba(15, 23, 42, 0.3);\r\n  }\r\n\r\n  &::-webkit-scrollbar-thumb {\r\n    background: rgba(79, 70, 229, 0.4);\r\n    border-radius: $border-radius-full;\r\n\r\n    &:hover {\r\n      background: rgba(79, 70, 229, 0.6);\r\n    }\r\n  }\r\n}\r\n\r\n.file-line {\r\n  &:hover {\r\n    color: $secondary-color;\r\n    background: rgba(79, 70, 229, 0.1);\r\n    border-radius: $border-radius;\r\n  }\r\n}\r\n\r\n.file-line-action:active {\r\n  color: $primary-color;\r\n  font-weight: bolder;\r\n}\r\n\r\n// Badge Styling\r\n.badge-container {\r\n  border: 2px solid $primary-color;\r\n  background: rgba(79, 70, 229, 0.1);\r\n  border-radius: $border-radius;\r\n}\r\n\r\n.badge-label {\r\n  color: $primary-color;\r\n  font-family: $font-heading;\r\n}\r\n\r\n// Comment Styling\r\n.comment {\r\n  background: rgba(79, 70, 229, 0.1);\r\n  color: $secondary-color;\r\n  border-left: 3px solid $primary-color;\r\n  padding-left: $layout-spacing